insert into public.challenges (id, type, level, status, data) values
  ('expr-a1-001', 'expression', 'A1', 'needs_review', '{"canonicalExpression": "avoir faim", "expressionAudioFile": "a1797ff7d2bd.mp3", "meaning": {"fr": "Avoir faim veut dire vouloir manger.", "pt": "Sentir fome, ter vontade de comer."}, "example": {"text": "J''ai très faim. Je veux manger.", "audioFile": "59379b90fd0a.mp3"}, "question": "Que signifie ''avoir faim'' ?", "options": ["Être fatigué", "Avoir soif", "Vouloir manger", "Être content"], "correctAnswer": "Vouloir manger", "explanation": "C''est une expression pour dire que vous voulez manger. On utilise ''avoir'' avec ''faim''.", "secondExample": {"text": "Nous avons faim après le sport.", "audioFile": "8feee3366530.mp3"}, "microActivity": {"prompt": "Il est midi. J''ai __________ !", "answer": "faim"}, "externalResources": [{"type": "dictionary", "url": "https://vertexaisearch.cloud.google.com/grounding-api-redirect/AUZIYQEdHxPWRNJJszDAN-slIjZ2ZcNQo6skzuyaP5mrK8XW3X9izSNsa7K30dHxgSeXfmt66VC4IehcjuXq6umJBpNee4ZcmjKzYTCPRhWgi1l8c3nVrfwAX5om2qMVkGUNLhcJ8eZx6pmm", "title": "cnrtl.fr", "sourceName": "cnrtl.fr", "description": "Definição detalhada, etimologia e exemplos de uso da palavra ''faim'' no Trésor de la Langue Française informatisé.", "quality": "high", "buttonLabel": "En savoir plus", "approved": true, "lastChecked": null}, {"type": "youglish", "url": "https://youglish.com/pronounce/avoir%20faim/french", "title": "YouGlish", "sourceName": "YouGlish", "description": "Ouça a expressão sendo usada por falantes reais em vários vídeos.", "quality": "high", "buttonLabel": "Voir en contexte", "approved": true, "lastChecked": null}]}'::jsonb),
  ('expr-a1-002', 'expression', 'A1', 'needs_review', '{"canonicalExpression": "avoir soif", "expressionAudioFile": "ae19ff4ddf12.mp3", "meaning": {"fr": "C''est quand on veut boire.", "pt": "É a sensação de querer beber."}, "example": {"text": "Il fait chaud, j''ai soif.", "audioFile": "5365f1e680f1.mp3"}, "question": "Que signifie cette expression ?", "options": ["Avoir faim", "Avoir soif", "Avoir froid", "Avoir chaud"], "correctAnswer": "Avoir soif", "explanation": "L''expression ''avoir soif'' veut dire qu''on a besoin de boire. C''est comme quand il fait très chaud.", "secondExample": {"text": "Après le sport, nous avons soif.", "audioFile": "3dde4ec21a1d.mp3"}, "microActivity": {"prompt": "J''ai couru 5 kilomètres, maintenant je __________.", "answer": "ai soif"}, "externalResources": [{"type": "dictionary", "url": "https://vertexaisearch.cloud.google.com/grounding-api-redirect/AUZIYQFXXhTBSMcLILA0jSO7rOyeD64I1fxj8cBrBHCP3BpZufBeaM6vSWKGgNHieNNKnzSNS89KDDmJI4mT0wr-zXwFB81-9JDKR1tTPQioy7FunwaD3WAavvwwXWCoz68H7tU2YjDBVeR2U6ZrC_GE5vnyVMQ=", "title": "larousse.fr", "sourceName": "larousse.fr", "description": "Definição clara, sinônimos, antônimos e exemplos de uso da expressão no Larousse.", "quality": "high", "buttonLabel": "En savoir plus", "approved": true, "lastChecked": null}, {"type": "youglish", "url": "https://youglish.com/pronounce/avoir%20soif/french", "title": "YouGlish", "sourceName": "YouGlish", "description": "Ouça a expressão sendo usada por falantes reais em vários vídeos.", "quality": "high", "buttonLabel": "Voir en contexte", "approved": true, "lastChecked": null}]}'::jsonb),
  ('expr-a1-003', 'expression', 'A1', 'needs_review', '{"canonicalExpression": "avoir raison", "expressionAudioFile": "13affc3609d3.mp3", "meaning": {"fr": "C''est quand on a la bonne opinion ou la bonne réponse.", "pt": "É quando você tem a opinião certa ou a resposta correta."}, "example": {"text": "Paul dit : ''Je pense que j''ai raison.''", "audioFile": "9a9de350efa8.mp3"}, "question": "Que signifie cette expression ?", "options": ["Être fatigué", "Avoir faim", "Avoir la bonne opinion", "Avoir soif"], "correctAnswer": "Avoir la bonne opinion", "explanation": "Quand vous avez raison, votre idée ou votre réponse est correcte. C''est le contraire d''avoir tort.", "secondExample": {"text": "Elle a raison, le magasin est fermé.", "audioFile": "d30b32c633be.mp3"}, "microActivity": {"prompt": "Tu dis que le film est bon. Je crois que tu __________.", "answer": "as raison"}, "externalResources": [{"type": "dictionary", "url": "https://vertexaisearch.cloud.google.com/grounding-api-redirect/AUZIYQEFK0YLHtSTr2K1QPen3doFDtxmB0hFiuOc1xG9Kkb4xy92BOcbOTw_FhfthdaKFAAvkuHqVqNrVKaIgazaywYdd0LYxAvvmUmTJai1k9TVqMtG1cPYjaV2Q8g1-lAKp7c=", "title": "cnrtl.fr", "sourceName": "cnrtl.fr", "description": "Explicação detalhada de ''raison'' com etimologia, definições e exemplos no CNRTL.", "quality": "high", "buttonLabel": "En savoir plus", "approved": true, "lastChecked": null}, {"type": "youglish", "url": "https://youglish.com/pronounce/avoir%20raison/french", "title": "YouGlish", "sourceName": "YouGlish", "description": "Ouça a expressão sendo usada por falantes reais em vários vídeos.", "quality": "high", "buttonLabel": "Voir en contexte", "approved": true, "lastChecked": null}]}'::jsonb),
  ('expr-a2-001', 'expression', 'A2', 'needs_review', '{"canonicalExpression": "coup de main", "expressionAudioFile": "7e8cf2e9417a.mp3", "meaning": {"fr": "Une aide, une assistance.", "pt": "Uma ajuda, uma mãozinha."}, "example": {"text": "J''ai besoin d''un coup de main pour porter ces cartons lourds.", "audioFile": "197a9e1af3eb.mp3"}, "question": "Que signifie cette expression ?", "options": ["Un problème difficile", "Une aide ponctuelle", "Une grande fatigue", "Une idée soudaine"], "correctAnswer": "Une aide ponctuelle", "explanation": "C''est une expression pour demander ou offrir de l''aide. Ça veut dire donner un coup de main.", "secondExample": {"text": "Mes voisins m''ont donné un coup de main pour déménager.", "audioFile": "3d85e1ce0bb1.mp3"}, "microActivity": {"prompt": "Peux-tu me donner un __________ pour finir ce travail ?", "answer": "coup de main"}, "externalResources": [{"type": "article", "url": "https://vertexaisearch.cloud.google.com/grounding-api-redirect/AUZIYQHWzuUhiqOwY5_-wc8ARWdA9x3UsurIXJz3rCPGohAGWOG5kJe1f8dFz-iv9QDJWZy5vjj6b7HDh2chOrdWWHK6zuD-xBf3mTAwmixnrQxoogBAOHVisv65r0bhCovX0t3FkY_EsVuialh5FlzfYw==", "title": "expressio.fr", "sourceName": "expressio.fr", "description": "Oferece uma explicação detalhada da significação, origem e nuances da expressão com exemplos.", "quality": "high", "buttonLabel": "En savoir plus", "approved": true, "lastChecked": null}, {"type": "youglish", "url": "https://youglish.com/pronounce/coup%20de%20main/french", "title": "YouGlish", "sourceName": "YouGlish", "description": "Ouça a expressão sendo usada por falantes reais em vários vídeos.", "quality": "high", "buttonLabel": "Voir en contexte", "approved": true, "lastChecked": null}]}'::jsonb),
  ('expr-a2-002', 'expression', 'A2', 'needs_review', '{"canonicalExpression": "avoir le trac", "expressionAudioFile": "2f4f2deb0eaf.mp3", "meaning": {"fr": "Avoir peur ou être nerveux avant de faire quelque chose d''important.", "pt": "Ficar nervoso ou com medo antes de fazer algo importante."}, "example": {"text": "Avant de monter sur scène, l''acteur a eu le trac.", "audioFile": "fd4c488562ac.mp3"}, "question": "Que signifie l''expression ''avoir le trac'' ?", "options": ["Être très content.", "Avoir peur ou être nerveux.", "Être fatigué.", "Avoir faim."], "correctAnswer": "Avoir peur ou être nerveux.", "explanation": "C''est un sentiment de nervosité avant une performance ou un événement.", "secondExample": {"text": "Quand elle doit parler en public, elle a toujours le trac.", "audioFile": "4a5c84ce9c07.mp3"}, "microActivity": {"prompt": "Demain, je dois présenter mon projet devant toute la classe. Je crois que je vais __________.", "answer": "avoir le trac"}, "externalResources": [{"type": "dictionary", "url": "https://vertexaisearch.cloud.google.com/grounding-api-redirect/AUZIYQE0Q5bovlo2nY83_Z4C214QtLMqZvy4TcXsHUSU_7RnC_0Pj19CGzh8KwJmnZ68DOJVPw5BKGLa6yDYxLfkNJ3_agUy9N72l76EMurBbPz-QP7hlFrqc3x5FXV1wza8x6A=", "title": "cnrtl.fr", "sourceName": "cnrtl.fr", "description": "Fornece uma definição detalhada, sinônimos e exemplos literários da expressão.", "quality": "high", "buttonLabel": "En savoir plus", "approved": true, "lastChecked": null}, {"type": "youglish", "url": "https://youglish.com/pronounce/avoir%20le%20trac/french", "title": "YouGlish", "sourceName": "YouGlish", "description": "Ouça a expressão sendo usada por falantes reais em vários vídeos.", "quality": "high", "buttonLabel": "Voir en contexte", "approved": true, "lastChecked": null}]}'::jsonb),
  ('expr-a2-003', 'expression', 'A2', 'needs_review', '{"canonicalExpression": "faire la grasse matinée", "expressionAudioFile": "1f91cc38f040.mp3", "meaning": {"fr": "Dormir tard le matin, ne pas se lever tout de suite.", "pt": "Dormir até tarde, acordar tarde."}, "example": {"text": "Dimanche, j''aime faire la grasse matinée et ne pas me lever tôt.", "audioFile": "f478208137b6.mp3"}, "question": "Que signifie cette expression ?", "options": ["Se réveiller très tôt le matin.", "Dormir beaucoup pendant la nuit.", "Se lever tard le matin, ne pas se presser pour sortir du lit.", "Faire une sieste pendant la journée."], "correctAnswer": "Se lever tard le matin, ne pas se presser pour sortir du lit.", "explanation": "Faire la grasse matinée veut dire dormir plus longtemps le matin. C''est quand on ne veut pas se lever tout de suite.", "secondExample": {"text": "Après la fête, nous avons fait la grasse matinée samedi.", "audioFile": "e9b49d253240.mp3"}, "microActivity": {"prompt": "Quand je suis en vacances, j''adore __________.", "answer": "faire la grasse matinée"}, "externalResources": [{"type": "dictionary", "url": "https://vertexaisearch.cloud.google.com/grounding-api-redirect/AUZIYQEn3D_47uUeNU2lDqp4nxXqMPZCRrf5eMQQuirjvIp51DXy45ppbAZdHrN6Algo-p8sqKScVwvIKCzLj-z0A3w9txzftX4HiyUtYPlfcszMnStMLzxtJ8utzQ-KThkNIQGQVfXMtpLPKPBonrOuYGByFJSOrTA=", "title": "wiktionary.org", "sourceName": "wiktionary.org", "description": "Fornece definição, etimologia e exemplos de uso da expressão.", "quality": "high", "buttonLabel": "En savoir plus", "approved": true, "lastChecked": null}, {"type": "youglish", "url": "https://youglish.com/pronounce/faire%20la%20grasse%20matin%C3%A9e/french", "title": "YouGlish", "sourceName": "YouGlish", "description": "Ouça a expressão sendo usada por falantes reais em vários vídeos.", "quality": "high", "buttonLabel": "Voir en contexte", "approved": true, "lastChecked": null}]}'::jsonb),
  ('expr-b2-001', 'expression', 'B2', 'needs_review', '{"canonicalExpression": "mettre les points sur les i", "expressionAudioFile": "5dd2e8210177.mp3", "meaning": {"fr": "Clarifier tous les détails, être précis sur tous les aspects d''une situation ou d''un accord.", "pt": "Esclarecer todos os detalhes, ser preciso sobre todos os aspetos de uma situação ou acordo."}, "example": {"text": "Bien que le projet ait été approuvé en principe, il restait encore à mettre les points sur les i concernant les détails budgétaires.", "audioFile": "74040711e0fa.mp3"}, "question": "Que signifie cette expression ?", "options": ["Être très fatigué", "Clarifier les derniers détails et être précis", "Se disputer pour des broutilles", "Prendre une décision hâtive"], "correctAnswer": "Clarifier les derniers détails et être précis", "explanation": "Cette expression signifie qu''il faut finaliser les choses en précisant tous les éléments importants pour éviter toute ambiguïté.", "secondExample": {"text": "Après la réunion, le manager a demandé à son équipe de mettre les points sur les i avant de soumettre le rapport final.", "audioFile": "639b20a731ed.mp3"}, "microActivity": {"prompt": "Avant de signer le contrat, nous devons absolument __________ pour éviter tout malentendu futur.", "answer": "mettre les points sur les i"}, "externalResources": [{"type": "dictionary", "url": "https://vertexaisearch.cloud.google.com/grounding-api-redirect/AUZIYQG-4HDZP5ksyCpPLH1Fo8wuCQcOl5ot5l5q1B-Inu9jzBxay843mCqQgKIuvGNqP7oiC9VGqHBy4LxDOrlbbPbz6x4b3HlQgoXvv5WKzHDnyAVWSvUzfKzCGWM23ibhcKWav9lc9kXkP0axXXpK6OU99X4nVQ==", "title": "wiktionary.org", "sourceName": "wiktionary.org", "description": "Definição, etimologia e exemplos de uso da expressão em um dicionário colaborativo.", "quality": "high", "buttonLabel": "En savoir plus", "approved": true, "lastChecked": null}, {"type": "youglish", "url": "https://youglish.com/pronounce/mettre%20les%20points%20sur%20les%20i/french", "title": "YouGlish", "sourceName": "YouGlish", "description": "Ouça a expressão sendo usada por falantes reais em vários vídeos.", "quality": "high", "buttonLabel": "Voir en contexte", "approved": true, "lastChecked": null}]}'::jsonb),
  ('expr-b2-002', 'expression', 'B2', 'needs_review', '{"canonicalExpression": "avoir un poil dans la main", "expressionAudioFile": "05f8fec38e34.mp3", "meaning": {"fr": "Ne pas aimer travailler, être paresseux.", "pt": "Ser preguiçoso, ter aversão ao trabalho."}, "example": {"text": "Bien que son projet soit ambitieux, il semble avoir un poil dans la main, car il repousse constamment les échéances.", "audioFile": "572902f35d1a.mp3"}, "question": "Que signifie cette expression ?", "options": ["Être très travailleur et efficace.", "Avoir une grande dextérité manuelle.", "Être paresseux et éviter le travail.", "Avoir une petite douleur au doigt."], "correctAnswer": "Être paresseux et éviter le travail.", "explanation": "Cette expression signifie que quelqu''un est très paresseux et n''aime pas faire d''efforts. C''est l''inverse de quelqu''un de travailleur.", "secondExample": {"text": "Malgré les critiques, elle n''a jamais eu un poil dans la main pour défendre ses idées.", "audioFile": "8161a79d42ec.mp3"}, "microActivity": {"prompt": "Il est étonnant de voir à quel point il __________ , lui qui est pourtant si doué.", "answer": "a un poil dans la main"}, "externalResources": [{"type": "dictionary", "url": "https://vertexaisearch.cloud.google.com/grounding-api-redirect/AUZIYQFqkWM3tRjT5oR3mLWNvsA79plcs3K1mzk7n6RvtJJxTSVg0fC0ygE-L-U534q5yGCP6iVWIbRKLf4PaL_nguK7_eiYv4ItAgWdobrCqlFOnwFc6qD6N2uvkxc4XFkVEEKhfyDdHG8BOmZq2ksG6wkJ4bwE", "title": "larousse.fr", "sourceName": "larousse.fr", "description": "Dicionário Larousse oferece definição precisa e confiável da expressão.", "quality": "high", "buttonLabel": "En savoir plus", "approved": true, "lastChecked": null}, {"type": "youglish", "url": "https://youglish.com/pronounce/avoir%20un%20poil%20dans%20la%20main/french", "title": "YouGlish", "sourceName": "YouGlish", "description": "Ouça a expressão sendo usada por falantes reais em vários vídeos.", "quality": "high", "buttonLabel": "Voir en contexte", "approved": true, "lastChecked": null}]}'::jsonb),
  ('expr-b2-003', 'expression', 'B2', 'needs_review', '{"canonicalExpression": "ne pas y aller de main morte", "expressionAudioFile": "5887c8ff6c46.mp3", "meaning": {"fr": "Agir avec beaucoup de force, d''énergie, sans retenue, de manière très directe ou virulente.", "pt": "Agir com muita força, energia, sem hesitação, de forma muito direta ou virulenta."}, "example": {"text": "Bien que le sujet soit délicat, le conférencier n''y est pas allé de main morte pour dénoncer les injustices sociales.", "audioFile": "03bbabd11c83.mp3"}, "question": "Que signifie cette expression ?", "options": ["Parler avec douceur et diplomatie.", "Agir avec force et détermination, sans modération.", "Exprimer son opinion avec hésitation.", "Critiquer de manière subtile et indirecte."], "correctAnswer": "Agir avec force et détermination, sans modération.", "explanation": "Cette expression signifie qu''on agit avec beaucoup d''énergie et de conviction, sans se retenir. Cela peut s''appliquer à une critique, une action ou une défense.", "secondExample": {"text": "Malgré les avertissements, elle a défendu son projet sans y aller de main morte face aux critiques acerbes.", "audioFile": "6aedee6b8d0f.mp3"}, "microActivity": {"prompt": "Face à cette injustice flagrante, il a décidé de __________ pour faire entendre sa voix.", "answer": "ne pas y aller de main morte"}, "externalResources": [{"type": "dictionary", "url": "https://vertexaisearch.cloud.google.com/grounding-api-redirect/AUZIYQG277FOstEQFri9PGMp2IFoMGd0nsFdHY_AGkpTfIB_lUyHfT2ZoqUGpOy1jEf7AnwRXFZdxtuo9MaR7SJYW9P1TZ9MlzrS14g0OzrfOC2sX4EchMmi0ylXftzpyNbl-w7ZrGSRm4uU8lw4GqGVyZAMULILMA==", "title": "wiktionary.org", "sourceName": "wiktionary.org", "description": "Fornece a definição, etimologia e exemplos de uso da expressão, com um alto nível de detalhe.", "quality": "high", "buttonLabel": "En savoir plus", "approved": true, "lastChecked": null}, {"type": "youglish", "url": "https://youglish.com/pronounce/ne%20pas%20y%20aller%20de%20main